describe('JavaScript Error Recovery', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should recover gracefully after a JavaScript error and display error message', () => {
    // Trigger a JavaScript error by manipulating the DOM
    cy.get('[data-testid="error-trigger"]').then((el) => {
      el.prop('innerHTML', '<script>throw new Error("Intentional JS error");</script>');
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Uncaught');

    // Verify app state is not lost
    cy.get('[data-testid="dashboard-title"]').should('be.visible');
    cy.get('[data-testid="dashboard-content"]').should('be.visible');

    // Verify navigation is still possible
    cy.get('[data-testid="dashboard-nav"]').should('be.visible');
    cy.get('[data-testid="dashboard-nav"]').click();
    cy.url().should('include', '/dashboard');
  });

  it('should not crash and handle multiple errors gracefully', () => {
    // Trigger multiple JavaScript errors
    cy.get('[data-testid="error-trigger"]').then((el) => {
      el.prop('innerHTML', '<script>throw new Error("First error");</script>');
      el.prop('innerHTML', '<script>throw new Error("Second error");</script>');
    });

    // Verify error message is displayed for each error
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Uncaught');

    // Verify app state is not lost
    cy.get('[data-testid="dashboard-title"]').should('be.visible');
    cy.get('[data-testid="dashboard-content"]').should('be.visible');

    // Verify navigation is still possible
    cy.get('[data-testid="dashboard-nav"]').should('be.visible');
    cy.get('[data-testid="dashboard-nav"]').click();
    cy.url().should('include', '/dashboard');
  });
});
